_choice_sdk() {
    local developer_dir sdk output=""
    if command -v xcodebuild >/dev/null 2>&1; then
        output="$(xcodebuild -showsdks 2>/dev/null)"
    fi
    if [[ -n "$output" ]]; then
        printf '%s\n' "$output" | gawk '
        $0 ~ /(^|[ \t])-sdk[ \t]/ {
            line = $0
            sub(/^[ \t]+/, "", line)
            sub(/[ \t]+-sdk[ \t]+/, "\t", line)
            split(line, parts, "\t")
            if (parts[2] != "") {
                printf "%s\t%s\n", parts[2], parts[1]
            }
        }'
        return 0
    fi
    developer_dir="$(xcode-select -p 2>/dev/null)"
    [[ -n "$developer_dir" ]] || return 0
    for sdk in "$developer_dir"/SDKs/*.sdk "$developer_dir"/Platforms/*/Developer/SDKs/*.sdk; do
        [[ -f "$sdk/SDKSettings.json" ]] || continue
        jq -b -r '[.CanonicalName, .DisplayName] | @tsv' "$sdk/SDKSettings.json" 2>/dev/null
    done
}

_choice_tool() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    local developer_dir dir file
    developer_dir="$(xcode-select -p 2>/dev/null)"
    [[ -n "$developer_dir" ]] || return 0
    for dir in "$developer_dir"/usr/bin \
        "$developer_dir"/Toolchains/*.xctoolchain/usr/bin \
        "$developer_dir"/Platforms/*/Developer/usr/bin \
        "$developer_dir"/Platforms/*/Developer/SDKs/*.sdk/usr/bin; do
        [[ -d "$dir" ]] || continue
        for file in "$dir"/*; do
            [[ -f "$file" && -x "$file" ]] || continue
            printf '%s\n' "${file##*/}"
        done
    done
}

_choice_toolchain() {
    local developer_dir toolchain
    developer_dir="$(xcode-select -p 2>/dev/null)"
    for toolchain in "$developer_dir"/Toolchains/*.xctoolchain \
        "$HOME"/Library/Developer/Toolchains/*.xctoolchain; do
        [[ -d "$toolchain" ]] || continue
        toolchain="${toolchain##*/}"
        printf '%s\n' "${toolchain%.xctoolchain}"
    done
}
